def preserve_tracking_boundary(apps, schema_editor):
    """Read-only regarding existing game state: no payouts or progress replay."""
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    Enrollment = apps.get_model("quests", "ChallengeEnrollment")
    Pin = apps.get_model("quests", "ChallengePin")
    Participant = apps.get_model("quests", "QuestParticipant")
    boundary = django.utils.timezone.now()
    alias = schema_editor.connection.alias
    for user in User.objects.using(alias).filter(role="child").select_related("family").iterator():
        Enrollment.objects.using(alias).get_or_create(user_id=user.pk, defaults={
            "starts_at": boundary, "timezone_name": user.family.timezone or "America/Phoenix",
        })
        participation = Participant.objects.using(alias).filter(user_id=user.pk, quest__status="active").order_by("pk").first()
        if participation:
            Pin.objects.using(alias).get_or_create(user_id=user.pk, defaults={"legacy_quest_id": participation.quest_id})


